package vn.hust.restaurant.controller;import java.sql.*;import java.util.*;import vn.hust.restaurant.model.MenuItem;import vn.hust.restaurant.service.MenuService;public class MenuController{private final MenuService s;public MenuController(MenuService s){this.s=s;}public List<MenuItem>list(String k,boolean a)throws SQLException{return s.list(k,a);}public Map<Integer,String>categories()throws SQLException{return s.categories();}public void save(MenuItem m)throws SQLException{s.save(m);}public void toggle(int id,boolean a)throws SQLException{s.toggle(id,a);}}